      var nextLit = pattern.charAt(pi);
      while (ui < uri.length && uri.charAt(ui) !== nextLit && uri.charAt(ui) !== '/') { ui++; }
      if (ui >= uri.length || uri.charAt(ui) !== nextLit) { return null; }
    } else {
