    var rrows = await getJson('r' + ri, []);
    for (var k = 0; k < rrows.length; k++) {
      if (matchPattern(uri, rrows[k][0]) || (altUri !== null && matchPattern(altUri, rrows[k][0]))) {
        kind = rrows[k][1]; break;
      }
    }
